from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    """
    Abstract base class for sorting algorithms. Defines the template method
   'sort()' that specifies the overall sorting process.
    """

    def __init__(self):
        pass

    @abstractmethod
    def sort(self, data):
        pass

    def swap(self, a, b):
        pass


class BubbleSort(SortAlgorithm):
    """
    Implementation of Bubble Sort algorithm.
    """
    def sort(self, data):
        n = len(data)
        for i in range(n):
            for j in range(0, n-i-1):
                if data[j] > data[j+1]:
                    data[j], data[j+1] = data[j+1], data[j]
        return

    def swap(self, a, b):
        data[a], data[b] = data[b], data[a]


class SelectionSort(SortAlgorithm):
    """
    Implementation of Selection Sort algorithm.
    """
    def sort(self, data):
        n = len(data)
        for i in range(n):
            min_index = i
            for j in range(i+1, n):
                if data[j] < data[min_index]:
                    min_index = j
            data[i], data[min_index] = data[min_index], data[i]
        return

    def swap(self, a, b):
        data[a], data[b] = data[b], data[a]


